-- CAB-0014: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin if exists(select 1 from public.entities where slug='pbrs' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='barisan-nasional'))) then raise exception 'CAB-0014: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party', parent.id,'pbrs','Parti Bersatu Rakyat Sabah','PBRS','government','A component party of Barisan Nasional (BN).','2026-11-09','[{"label": "SPR · registered party symbols", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}, {"label": "PBRS · Arthur Kurup (1 Jun 2026)", "url": "https://bernama.com/en/news.php?id=2563552"}]'::jsonb from public.entities parent where parent.slug='barisan-nasional' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='pbrs' and type='party') then raise exception 'CAB-0014: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0014: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='barisan-nasional' and type='alliance') then raise exception 'CAB-0014: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('arthur-joseph-kurup','ramanan-ramakrishnan') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0014: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('pensiangan','sungai buloh') and slug not in ('arthur-joseph-kurup','ramanan-ramakrishnan')) then raise exception 'CAB-0014: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0014:%' and (m.source_type <> 'editorial' or e.slug not in ('arthur-joseph-kurup','ramanan-ramakrishnan') or m.import_key not like 'CAB-0014:' || e.slug || ':%')) then raise exception 'CAB-0014: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'arthur-joseph-kurup','Arthur Joseph Kurup','government','Minister of Natural Resources and Environmental Sustainability','Pensiangan','Sabah','Arthur Joseph Kurup is Minister of Natural Resources and Environmental Sustainability. He represents Pensiangan, Sabah, in the Dewan Rakyat. He is a member of Parti Bersatu Rakyat Sabah (PBRS).','https://www.nres.gov.my/','/portraits/arthur-joseph-kurup.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P182.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Pensiangan", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4221"}, {"label": "PBRS · Arthur Kurup (1 Jun 2026)", "url": "https://bernama.com/en/news.php?id=2563552"}]'::jsonb from public.entities parent where parent.slug='pbrs' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'ramanan-ramakrishnan','Ramanan Ramakrishnan','government','Minister of Human Resources','Sungai Buloh','Selangor','Ramanan Ramakrishnan is Minister of Human Resources. He represents Sungai Buloh, Selangor, in the Dewan Rakyat. He is a member of Parti Keadilan Rakyat (PKR).','https://www.mohr.gov.my/','/portraits/ramanan-ramakrishnan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P107.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Sungai Buloh", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4146"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('arthur-joseph-kurup','ramanan-ramakrishnan') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0014: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0014:arthur-joseph-kurup:climate-change-bill','Table the Climate Change Bill, subject to Cabinet approval','Environment','in_progress',null,null,'2026-10-07','https://web26.bernama.com/en/region/news.php?id=2616564','2026-10-07','https://web26.bernama.com/en/region/news.php?id=2616564','Arthur said the Climate Change Bill was intended for the current parliamentary sitting once Cabinet approval was obtained.','His update reports drafting approval in principle and completed state-government engagement. This supports ongoing preparation, not first reading, passage or commencement. The tabling condition remains explicit; a firm unconditional deadline and completion percentage were not established.','2026-11-09','editorial',false from public.entities e where e.slug='arthur-joseph-kurup' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0014:ramanan-ramakrishnan:skilled-workforce-35-2030','Reach a 35% skilled workforce by 2030','Education','in_progress',null,'2030-12-31','2026-01-15','https://www.mohr.gov.my/pdf/2026/KSM.%20100-2_1_1%20JLD5%20%2855%29.pdf','2026-08-31','https://www.bernama.com/en/news.php?id=2601331','KESUMA’s account of Ramanan’s 2026 address states a 35% skilled-workforce target by 2030, supported by TVET and targeted training.','His August update describes continuing workforce-skills programmes. Programme offers and training capacity do not establish the national skilled-workforce share. The target remains in progress with no numerical completion assigned.','2026-11-09','editorial',false from public.entities e where e.slug='ramanan-ramakrishnan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0014:ramanan-ramakrishnan:ai-access-100000-youths','Provide AI-learning access for 100,000 youths','Digital',null,null,null,'2026-08-31','https://www.bernama.com/en/news.php?id=2601331',null,null,'Ramanan endorsed the shared AI for the People initiative targeting 100,000 youths aged 18–30 and broader access to AI skills.','The report describes the new initiative and related workforce programmes. It does not establish 100,000 participants completing the prescribed modules. Separate MyMahir training capacity is not substituted for this target; outcome status, deadline and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='ramanan-ramakrishnan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

